let lang='it';try{lang=localStorage.getItem('portfolio-language')||'it'}catch{}if(!['it','en'].includes(lang))lang='it';
const main=document.querySelector('main'),reduced=matchMedia('(prefers-reduced-motion: reduce)'),t=(it,en)=>lang==='it'?it:en,v=x=>typeof x==='object'?x[lang]:x,asset=(name,small=false)=>`assets/${name}${small?'-sm':''}.webp`,num=n=>String(n).padStart(2,'0');
let cleanup=()=>{},galleryItems=[],lightIndex=0,selected=0;
const image=(name,alt,small=false,eager=false)=>`<img src="${asset(name,small)}" alt="${alt}" width="${imageDimensions[name]?.width||1200}" height="${imageDimensions[name]?.height||800}" loading="${eager?'eager':'lazy'}" decoding="async" draggable="false">`;
const footer=()=>`<footer><span>© ${new Date().getFullYear()} FILIPPO ANTONIO VISENTIN</span><a href="#home">${t('Torna nello spazio','Back to the space')} ↗</a></footer>`;
const captions={
'compluvio_render_interno_01':P('Coltivare insieme','Growing together'),'compluvio_render_interno_02':P('Luce e materia','Light and matter'),'compluvio_sezioni_tipo':P('Piante e sezione','Plans and section'),'compluvio_assonometria_luogo':P('Cascina Linterno — contesto','Cascina Linterno — context'),
'soundplace_assonometria':P('Walking Tree — assonometria','Walking Tree — axonometric view'),'soundplace_luogo_ponte':P('Ponte Vanoni — il luogo','Ponte Vanoni — the place'),'soundplace_storyboard':P('Storyboard del servizio proposto','Proposed service storyboard'),
'presence_interno_02':P('Soglie e riflessi','Thresholds and reflections'),'presence_interno_03':P('Il centro dello spazio','The centre of the space'),'presence_prospetti':P('Piante e prospetti','Plans and elevations'),
'poliedro_composizione_dettaglio':P('La composizione','The arrangement'),'poliedro_dettaglio_seduta_03':P('Dettaglio seduta','Seat detail'),'poliedro_dettaglio_seduta_04':P('Geometria e drenaggio','Geometry and drainage'),'poliedro_lampada':P('Il modulo luminoso','The light module'),'poliedro_schizzo_concept':P('Schizzi di relazione','Sketching relationships')};
function caption(name){if(captions[name])return v(captions[name]);if(name.startsWith('monoblock-')){const n=+name.split('-')[1];return n>=46?t('Allestimento — vista ','Exhibition — view ')+(n-45):({30:t('Planimetria — I','Floor plan — I'),31:t('Planimetria — II','Floor plan — II'),36:t('Sistema a binario','Rail system'),37:t('Connessioni','Connections'),38:t('Tende e soglie','Curtains and thresholds'),39:t('Trasformazione della materia','Material transformation')})[n];}return name.replace(/^(bivacuum-|oltreetrusco_)/,'').replace(/^\d+-/,'').replaceAll('_',' ').replaceAll('-',' ')}
function render(){cleanup();cleanup=()=>{};document.documentElement.lang=lang;document.querySelectorAll('[data-it]').forEach(e=>e.textContent=e.dataset[lang]);document.querySelector('#language').textContent=lang==='it'?'EN ↗':'IT ↗';document.querySelector('#language').ariaLabel=lang==='it'?'Switch to English':'Passa a italiano';const route=location.hash.slice(1)||'home';document.body.className=route==='home'?'is-home':'';if(route==='home')home();else if(route==='index')index();else if(route==='about')about();else{const p=projects.find(p=>p.id===route);p?project(p):index()}document.title=route==='home'?'Filippo Antonio Visentin — Selected works':`${projects.find(p=>p.id===route)?.name||t('Portfolio','Portfolio')} — Filippo Antonio Visentin`;}
function home(){main.innerHTML=`<section class="home"><div class="scene-top"><span>${t('Archivio aperto / 07 progetti','Open archive / 07 projects')}</span><span>${t('Spazio, materia, persone','Space, matter, people')} · 45°28′ N</span></div><div class="scene-word" aria-hidden="true">IN RELAZIONE.</div><div class="scene" aria-label="${t('Galleria tridimensionale dei progetti','Three-dimensional project gallery')}"><div class="world">${projects.map((p,i)=>`<button class="plane" data-i="${i}" aria-label="${t('Apri','Open')} ${p.name}">${image(p.cover,p.name,true,true)}<span class="plane-label"><span>${num(i+1)} / ${p.name}</span><span>↗</span></span></button>`).join('')}</div></div><div class="scene-bottom"><div class="scene-instruction">${t('Trascina per cambiare prospettiva.','Drag to change your perspective.')}<br><a href="#index">${t('Visualizza indice','View index')} ↗</a></div><a class="active-project" href="#${projects[selected].id}" aria-live="polite"></a><div class="scene-controls"><button id="previous" aria-label="${t('Progetto precedente','Previous project')}">←</button><span class="counter"></span><button id="next" aria-label="${t('Progetto successivo','Next project')}">→</button></div></div></section>`;
 const scene=main.querySelector('.scene'),planes=[...main.querySelectorAll('.plane')];let target=selected,current=selected,raf=0,drag=false,startX=0,startY=0,startTarget=0,moved=false,panX=0,panY=0;const N=projects.length;
 function label(){selected=((Math.round(target)%N)+N)%N;const p=projects[selected];const a=main.querySelector('.active-project');a.href='#'+p.id;a.innerHTML=`<div><p>${v(p.type)}</p><h1>${p.name}</h1></div><span class="open">↗</span>`;main.querySelector('.counter').textContent=`${num(selected+1)} / ${num(N)}`;}
 function draw(){const mobile=innerWidth<700;planes.forEach((el,i)=>{let d=((i-current+N*1.5)%N+N)%N-N/2;const x=d*(mobile?255:365),z=-Math.abs(d)*185,y=Math.sin(d*1.1)*52;el.style.transform=`translate3d(${x+panX}px,${y+panY}px,${z}px) rotateY(${-d*13}deg) rotateZ(${d*2}deg)`;el.style.opacity=Math.abs(d)>2.8?'0':String(1-Math.abs(d)*.13);el.style.pointerEvents=Math.abs(d)>2.8?'none':'auto';el.tabIndex=Math.abs(d)<.5?0:-1;el.style.zIndex=String(20-Math.round(Math.abs(d)*5));});}
 function tick(){current=reduced.matches?target:current+(target-current)*.085;draw();if(Math.abs(target-current)>.001)raf=requestAnimationFrame(tick);else{current=target;raf=0;draw()}}
 function move(delta){target+=delta;label();if(!raf)raf=requestAnimationFrame(tick)}
 main.querySelector('#previous').onclick=()=>move(-1);main.querySelector('#next').onclick=()=>move(1);
 scene.onpointerdown=e=>{if(e.button!==0)return;drag=true;moved=false;startX=e.clientX;startY=e.clientY;startTarget=target;};
 const pointermove=e=>{if(!drag)return;if(Math.abs(e.clientX-startX)>8||Math.abs(e.clientY-startY)>8)moved=true;if(Math.abs(e.clientY-startY)>Math.abs(e.clientX-startX)&&e.pointerType==='touch'){drag=false;return}target=startTarget-(e.clientX-startX)/(innerWidth<700?240:365);label();if(!raf)raf=requestAnimationFrame(tick)};
 const pointerup=()=>{if(!drag)return;drag=false;target=Math.round(target);label();if(!raf)raf=requestAnimationFrame(tick)};
 window.addEventListener('pointermove',pointermove);window.addEventListener('pointerup',pointerup);window.addEventListener('pointercancel',pointerup);
 planes.forEach((el,i)=>el.onclick=e=>{if(moved){e.preventDefault();return}location.hash=projects[i].id});
 const key=e=>{if(e.target.closest('nav')||e.target.tagName==='INPUT')return;if(e.key==='ArrowRight'){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}};window.addEventListener('keydown',key);window.addEventListener('resize',draw);const hide=()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;current=target}else draw()};document.addEventListener('visibilitychange',hide);label();draw();cleanup=()=>{cancelAnimationFrame(raf);window.removeEventListener('pointermove',pointermove);window.removeEventListener('pointerup',pointerup);window.removeEventListener('pointercancel',pointerup);window.removeEventListener('keydown',key);window.removeEventListener('resize',draw);document.removeEventListener('visibilitychange',hide)};
}
function index(){main.innerHTML=`<section class="page"><div class="page-head eyebrow"><span>${t('Lavori selezionati','Selected works')}</span><a href="#home">${t('Vista spaziale','Spatial view')} ↗</a></div><h1>${t('Forme di relazione.','Forms of connection.')}</h1><div>${projects.map((p,i)=>`<a class="index-row" href="#${p.id}"><span class="num">${num(i+1)}</span>${image(p.cover,p.name,true)}<h2>${p.name}</h2><span class="category">${v(p.type)}</span><span>↗</span></a>`).join('')}</div>${footer()}</section>`;}
function special(p){if(p.id==='bivacuum')return `<section class="chapter"><span class="eyebrow">${t('Esplora la trasformazione','Explore the transformation')}</span><h2>${t('Un interno, due tempi.','One interior, two rhythms.')}</h2><p>${t('Sposta il cursore per confrontare le configurazioni del rifugio.','Move the slider to compare the shelter’s configurations.')}</p><div class="comparison">${image('bivacuum-14-interior-day',t('Configurazione giorno','Day configuration'))}<img class="after" src="${asset('bivacuum-15-interior-night')}" alt="${t('Configurazione notte','Night configuration')}" loading="lazy"></div><label class="range-label" for="compare"><span>${t('Giorno','Day')}</span><span>${t('Notte','Night')}</span></label><input id="compare" type="range" min="0" max="100" value="50" aria-label="${t('Confronto giorno e notte','Day and night comparison')}"></section>`;
 if(p.id==='oltreetrusco'||p.id==='soundplace'||p.id==='monoblock'){let stages=p.id==='oltreetrusco'?[P('Percorso guidato','Guided route'),P('Confine permeabile','Permeable boundary'),P('Esplorazione libera','Free exploration')]:p.id==='soundplace'?[P('Prenotazione','Booking'),P('Attivazione','Activation'),P('Esperienza','Experience')]:[P('Prodotto','Product'),P('Risorsa','Resource'),P('Responsabilità','Responsibility')];let descriptions=p.id==='oltreetrusco'?[P('La prima sala definisce un itinerario chiaro e obbligato. Il limite orienta la lettura.','The first room defines a clear, prescribed route. Boundaries guide interpretation.'),P('Nella seconda sala i confini si interrompono: il percorso diventa parzialmente libero.','In the second room boundaries break apart: the route becomes partly open.'),P('Nella terza sala gli elementi sono distribuiti nello spazio. Il visitatore sceglie il proprio percorso.','In the third room elements are distributed through the space. Visitors choose their own route.')]:p.id==='soundplace'?[P('Lo storyboard propone un’app per individuare e prenotare il modulo.','The storyboard proposes an app for finding and booking the module.'),P('L’interazione con il modulo segna l’inizio dell’esperienza condivisa.','Interacting with the module marks the start of the shared experience.'),P('La musica e la sosta costruiscono un’occasione di incontro; il servizio immagina anche un feedback finale.','Music and rest create an opportunity to meet; the proposed service also includes feedback afterwards.')]:[P('La sedia monoblocco racconta una produzione industriale capace di ottimizzare forma, tempo e costo.','The monobloc chair tells the story of industrial production optimising form, time and cost.'),P('La materia continua a esistere dopo l’uso. L’allestimento porta in primo piano il suo possibile ritorno nel ciclo produttivo.','Material continues to exist after use. The exhibition foregrounds its possible return to the production cycle.'),P('Progettare un oggetto significa interrogarsi anche sulle infrastrutture che ne rendono possibile il fine vita.','Designing an object also means questioning the infrastructure that makes its end of life possible.')];window.chapterDescriptions=descriptions;return `<section class="chapter"><span class="eyebrow">${t('Leggere il progetto','Reading the project')}</span><h2>${t('Un percorso, più prospettive.','One journey, multiple perspectives.')}</h2><div class="tabs">${stages.map((s,i)=>`<button data-stage="${i}" aria-pressed="${i===0}">${num(i+1)} / ${v(s)}</button>`).join('')}</div><p class="stage-copy" aria-live="polite">${v(descriptions[0])}</p></section>`}return ''}
function project(p){galleryItems=[p.cover,...p.gallery];main.innerHTML=`<article class="page"><div class="project-top"><a href="#index">← ${t('Tutti i progetti','All projects')}</a><span>${v(p.type)} ${p.year?' / '+p.year:''}</span></div><h1 class="project-title">${p.name}</h1><div class="project-hero"><button data-light="0" aria-label="${t('Ingrandisci immagine','Enlarge image')}">${image(p.cover,p.name,false,true)}</button></div><div class="project-copy"><div><h2>${v(p.subtitle)}</h2><div class="meta">${v(p.meta)}</div><div class="team"><br>${t('Progetto di','Designed by')}<br>${p.team}</div></div><div><p>${v(p.intro)}</p><p>${v(p.text)}</p>${p.id==='presence'?'<a href="#poliedro">↗ POLIEDRO</a>':p.id==='poliedro'?'<a href="#presence">↗ A MATTER OF PRESENCE</a>':''}</div></div>${special(p)}<div class="gallery">${p.gallery.map((g,i)=>`<figure><button data-light="${i+1}" aria-label="${t('Ingrandisci','Enlarge')} ${caption(g)}">${image(g,caption(g))}</button><figcaption><span>${caption(g)}</span><span>${num(i+1)}</span></figcaption></figure>`).join('')}</div><a class="next" href="#${projects[(projects.indexOf(p)+1)%projects.length].id}"><span class="eyebrow">${t('Progetto successivo','Next project')}</span><strong>${projects[(projects.indexOf(p)+1)%projects.length].name} ↗</strong></a>${footer()}</article>`;main.querySelectorAll('[data-light]').forEach(b=>b.onclick=()=>openLight(+b.dataset.light));const range=main.querySelector('#compare');if(range)range.oninput=()=>main.querySelector('.comparison').style.setProperty('--split',range.value+'%');main.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{main.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('.stage-copy').textContent=v(window.chapterDescriptions[+b.dataset.stage])});}
function about(){main.innerHTML=`<section class="page"><div class="page-head eyebrow"><span>${t('Info / Contatti','About / Contact')}</span><span>FAV — PORTFOLIO</span></div><h1>${t('La forma nasce<br>dall’esperienza.','Form begins<br>with experience.')}</h1><div class="about-grid">${image('about_ritratto','Filippo Antonio Visentin',false,true)}<div><h2>Filippo Antonio<br>Visentin</h2><p>${t('Sono un designer di prodotto e d’interni. La mia ricerca muove dall’osservazione delle interazioni tra le persone e dei modi reali in cui spazi e oggetti vengono abitati e utilizzati.','I am a product and interior designer. My research starts with observing interactions between people and the real ways in which spaces and objects are inhabited and used.')}</p><p>${t('Ricerco una forma che derivi dall’uso e non lo preceda. Interpreto il design come un gesto che accompagna l’esperienza, cercando l’equilibrio tra rigore tecnico e qualità materica.','I look for form that follows use rather than preceding it. I see design as a gesture that supports experience, seeking a balance between technical rigour and material quality.')}</p><dl><dt>${t('Formazione','Education')}</dt><dd>Politecnico di Milano — ${t('Design degli Interni · dal 2023','Interior Design · from 2023')}<br>${t('Certificazione stampa 3D · 2025','3D printing certification · 2025')}<br>ITI Rossi, Vicenza — ${t('Telecomunicazioni','Telecommunications')}</dd><dt>${t('Strumenti','Tools')}</dt><dd>Rhino · Grasshopper · Blender · AutoCAD · Inventor · V-Ray<br>Illustrator · InDesign · Photoshop<br>HTML · JavaScript · C# · ${t('Prototipazione e stampa 3D','Prototyping and 3D printing')}</dd><dt>${t('Esperienze','Experience')}</dt><dd>2025–2026 · Aldi, Milano — ${t('Addetto vendita','Sales assistant')}<br>2021–2023 · La Capannina, Barbarano Vicentino — ${t('Responsabile di sala','Front-of-house manager')}</dd><dt>${t('Lingue e interessi','Languages and interests')}</dt><dd>${t('Italiano C2 · Inglese B2 · Francese B1','Italian C2 · English B2 · French B1')}<br>${t('Montagna, alpinismo, stampa 3D e droni FPV.','Mountains, climbing, 3D printing and FPV drones.')}</dd></dl></div></div><section class="contact"><span class="eyebrow">${t('Iniziamo una conversazione','Start a conversation')}</span><h2>${t('Mettiamoci in relazione.','Let’s connect.')}</h2><a href="mailto:filippoantonio.visentin@mail.polimi.it">filippoantonio.visentin@mail.polimi.it ↗</a></section>${footer()}</section>`;}
const light=document.querySelector('#lightbox');function openLight(i){lightIndex=(i+galleryItems.length)%galleryItems.length;const g=galleryItems[lightIndex];light.querySelector('img').src=asset(g);light.querySelector('img').alt=caption(g);light.querySelector('figcaption').textContent=caption(g);light.querySelector('.light-count').textContent=`${num(lightIndex+1)} / ${num(galleryItems.length)}`;if(!light.open){light.showModal();document.body.style.overflow='hidden'}}light.querySelector('.close').onclick=()=>light.close();light.onclose=()=>document.body.style.overflow='';light.querySelector('.light-prev').onclick=()=>openLight(lightIndex-1);light.querySelector('.light-next').onclick=()=>openLight(lightIndex+1);light.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();openLight(lightIndex+1)}if(e.key==='ArrowLeft'){e.preventDefault();openLight(lightIndex-1)}});document.querySelector('#language').onclick=()=>{lang=lang==='it'?'en':'it';try{localStorage.setItem('portfolio-language',lang)}catch{}render()};window.addEventListener('hashchange',()=>{if(light.open)light.close();render();window.scrollTo(0,0);main.focus({preventScroll:true})});render();
